"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[4384],{94040(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>a,metadata:()=>r,toc:()=>c});var s=t(74848),i=t(28453);const a={title:"Change One Estimate, Earn Billions More: How to Spot Legal Window Dressing Yourself",date:new Date("2026-11-06T00:00:00.000Z"),author:"@Mythogen Engine",lang:"en",section:"finance",topic:"t-hardware",category:"\u534a\u5c0e\u9ad4\u9031\u671f",series:{order:2},slug:"/finance/change-one-estimate-earn-billions-more",article_tags:{zh:["\u6703\u8a08\u4f30\u8a08","\u6298\u820a\u5e74\u9650","\u8ca1\u5831\u5206\u6790","Intel","\u5fae\u8edf"],en:["accounting-estimates","useful-life","financial-analysis","intel","microsoft"]},keywords:["Accounting Estimates","Useful Life","Macronix","Intel","Microsoft","Window Dressing"],summary:"Deconstructing accounting estimate revisions at Intel, Microsoft, and Macronix to reveal how extending useful lives legally inflates profits.",description:"Deconstructing accounting estimate revisions at Intel, Microsoft, and Macronix to reveal how extending useful lives legally inflates profits.",status:"published",reading_time:9},o="Change One Estimate, Earn Billions More: How to Spot Legal Window Dressing Yourself",r={id:"finance/ai-in-financial-statements/\u6539\u4e00\u500b\u4f30\u8a08\uff0c\u591a\u8cfa\u5e7e\u5341\u5104",title:"Change One Estimate, Earn Billions More: How to Spot Legal Window Dressing Yourself",description:"Deconstructing accounting estimate revisions at Intel, Microsoft, and Macronix to reveal how extending useful lives legally inflates profits.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/finance/ai-in-financial-statements/02-\u6539\u4e00\u500b\u4f30\u8a08\uff0c\u591a\u8cfa\u5e7e\u5341\u5104.md",sourceDirName:"finance/ai-in-financial-statements",slug:"/finance/change-one-estimate-earn-billions-more",permalink:"/en/docs/finance/change-one-estimate-earn-billions-more",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:2,frontMatter:{title:"Change One Estimate, Earn Billions More: How to Spot Legal Window Dressing Yourself",date:"2026-11-06T00:00:00.000Z",author:"@Mythogen Engine",lang:"en",section:"finance",topic:"t-hardware",category:"\u534a\u5c0e\u9ad4\u9031\u671f",series:{order:2},slug:"/finance/change-one-estimate-earn-billions-more",article_tags:{zh:["\u6703\u8a08\u4f30\u8a08","\u6298\u820a\u5e74\u9650","\u8ca1\u5831\u5206\u6790","Intel","\u5fae\u8edf"],en:["accounting-estimates","useful-life","financial-analysis","intel","microsoft"]},keywords:["Accounting Estimates","Useful Life","Macronix","Intel","Microsoft","Window Dressing"],summary:"Deconstructing accounting estimate revisions at Intel, Microsoft, and Macronix to reveal how extending useful lives legally inflates profits.",description:"Deconstructing accounting estimate revisions at Intel, Microsoft, and Macronix to reveal how extending useful lives legally inflates profits.",status:"published",reading_time:9},sidebar:"finance",previous:{title:"One Industry Code, Two Opposite Moves",permalink:"/en/docs/finance/one-industry-code-two-opposite-moves"},next:{title:"Where Did the Costs Go?",permalink:"/en/docs/finance/where-did-the-costs-go"}},l={},c=[{value:"One machine, two ways to count",id:"one-machine-two-ways-to-count",level:2},{value:"Case 1: Intel, 2023",id:"case-1-intel-2023",level:2},{value:"Case 2: Microsoft, fiscal 2023",id:"case-2-microsoft-fiscal-2023",level:2},{value:"Case 3: Macronix, 2016",id:"case-3-macronix-2016",level:2},{value:"What the three cases share",id:"what-the-three-cases-share",level:2},{value:"How to check it yourself",id:"how-to-check-it-yourself",level:2},{value:"A counterexample",id:"a-counterexample",level:3},{value:"Public is not the same as seen",id:"public-is-not-the-same-as-seen",level:2},{value:"Data and method",id:"data-and-method",level:2},{value:"AI disclosure",id:"ai-disclosure",level:2},{value:"Disclaimer",id:"disclaimer",level:2}];function h(e){const n={a:"a",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"change-one-estimate-earn-billions-more-how-to-spot-legal-window-dressing-yourself",children:"Change One Estimate, Earn Billions More: How to Spot Legal Window Dressing Yourself"})}),"\n",(0,s.jsx)(n.p,{children:"2026-11-06 \xb7 @Mythogen Engine"}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"AI in the Financial Statements, Part 2"})}),"\n",(0,s.jsx)(n.p,{children:'When people hear "window dressing" in accounts, most think of fraud: fake orders, forged invoices, a bribed auditor. That happens, but rarely, because the price is too high.'}),"\n",(0,s.jsx)(n.p,{children:"The more common method is entirely legal. A company changes one accounting estimate, and the same business produces billions more in profit. The change is written in the annual report, the auditor signs off, the regulator files the announcement. Procedurally, it is flawless."}),"\n",(0,s.jsx)(n.p,{children:"This kind of practice is common, and not confined to a few companies."}),"\n",(0,s.jsx)(n.p,{children:"This article takes apart three public cases: Intel, Microsoft, and Taiwan's Macronix. All three changed the same number: how many years their equipment can be used. Then it shows how to find this yourself, using financial statements anyone can get."}),"\n",(0,s.jsxs)(n.p,{children:["Why now. Part 1 of this series covered the expansion of Taiwan's AI supply chain; the capital spent today becomes depreciation over the following years. Bank of America estimates that TSMC's depreciation expense could grow at a compound annual rate of 20% from 2026 to 2028 (",(0,s.jsx)(n.a,{href:"https://money.udn.com/money/story/5607/9702316",children:"Economic Daily News"}),"); Capital Securities estimates ASE's depreciation this year will rise 12% to 15% (",(0,s.jsx)(n.a,{href:"https://wantrich.chinatimes.com/news/20261030900228-420101",children:"China Times"}),'). The larger the depreciation, the larger the effect of the "useful life" estimate on profit.']}),"\n",(0,s.jsx)(n.h2,{id:"one-machine-two-ways-to-count",children:"One machine, two ways to count"}),"\n",(0,s.jsx)(n.p,{children:'A factory spends NT$10 billion on a batch of equipment. The NT$10 billion is not booked as an expense all at once; it is spread over the "estimated useful life", one slice a year. That slice is depreciation.'}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Estimated useful life"}),(0,s.jsx)(n.th,{children:"Annual depreciation"}),(0,s.jsx)(n.th,{children:"Annual profit (all else equal)"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"5 years"}),(0,s.jsx)(n.td,{children:"NT$2 billion"}),(0,s.jsx)(n.td,{children:"Baseline"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"8 years"}),(0,s.jsx)(n.td,{children:"NT$1.25 billion"}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.strong,{children:"NT$750 million higher"})})]})]})]}),"\n",(0,s.jsx)(n.p,{children:'The machines have not changed, the products have not changed, the customers have not changed. Management simply judged that "this batch can be used for three more years", and profit rises by NT$750 million a year.'}),"\n",(0,s.jsxs)(n.p,{children:["Useful life is an estimate, and accounting standards allow companies to adjust it to reflect actual use (",(0,s.jsx)(n.a,{href:"https://www2.deloitte.com/content/dam/Deloitte/tw/Documents/audit/IFRS/tw-A079.pdf",children:"Deloitte Taiwan"}),"). A reasonable estimate reflects reality more accurately; an over-optimistic one pushes today's costs into the future. In the current period's accounts, the two look exactly the same."]}),"\n",(0,s.jsx)(n.h2,{id:"case-1-intel-2023",children:"Case 1: Intel, 2023"}),"\n",(0,s.jsxs)(n.p,{children:["From January 2023, Intel extended the estimated useful life of some fab production equipment from 5 years to 8. By its own estimate, the change cut that year's depreciation by US$4.2 billion, raised gross margin by about US$2.5 billion and lowered R&D expense by US$400 million (",(0,s.jsx)(n.a,{href:"https://www.sec.gov/Archives/edgar/data/50863/000005086324000055/a2024ars202310k.htm",children:"Intel 2023 annual report"}),")."]}),"\n",(0,s.jsx)(n.p,{children:"The reason the company gave: the same tools can be reused across several process generations. That reason may well hold."}),"\n",(0,s.jsxs)(n.p,{children:["But the same year had another entry. In Q1 2023, Intel offered incentives to some customers to respond to competition and ",(0,s.jsx)(n.strong,{children:"accelerate their purchases"}),"; these contributed about US$900 million of revenue that quarter (",(0,s.jsx)(n.a,{href:"https://www.sec.gov/Archives/edgar/data/50863/000005086323000028/intc-20230401.htm",children:"Intel Q1 2023 quarterly report"}),")."]}),"\n",(0,s.jsx)(n.p,{children:"On one side, costs spread further into the future; on the other, revenue pulled from the future into today. Both are legal, and both are in the filings."}),"\n",(0,s.jsx)(n.p,{children:"The same annual report also contains another sentence: if the company's manufacturing strategy does not succeed, the related plant and equipment may need to be impaired. Extending the useful life assumes the machines really can be used for the full eight years."}),"\n",(0,s.jsx)(n.h2,{id:"case-2-microsoft-fiscal-2023",children:"Case 2: Microsoft, fiscal 2023"}),"\n",(0,s.jsxs)(n.p,{children:["In July 2022, Microsoft extended the estimated useful life of servers and network equipment from 4 years to 6, effective from fiscal 2023. The change raised operating income for that year by US$3.7 billion, net income by US$3.0 billion and earnings per share by US$0.40 (",(0,s.jsx)(n.a,{href:"https://www.sec.gov/Archives/edgar/data/789019/000095017023035122/msft-20230630.htm",children:"Microsoft 2023 annual report"}),"). It was not the first time: it had already extended them once in July 2020 (",(0,s.jsx)(n.a,{href:"https://www.sec.gov/Archives/edgar/data/789019/000156459022026876/msft-10k_20220630.htm",children:"Microsoft 2022 annual report"}),")."]}),"\n",(0,s.jsxs)(n.p,{children:["The company's reason was that software had improved how efficiently the equipment runs, together with technological progress. In the same period, Amazon and Oracle also extended the useful life of their servers (",(0,s.jsx)(n.a,{href:"https://bedrock.substack.com/p/accounting-policy-changes-boost-tech",children:"Bedrock"}),"). This may be a real change in the industry, not necessarily deliberate dressing-up."]}),"\n",(0,s.jsxs)(n.p,{children:["But the same annual report contains another number. In January 2023, Microsoft announced it would cut about 10,000 jobs and took a US$1.2 billion charge for it (",(0,s.jsx)(n.a,{href:"https://www.sec.gov/Archives/edgar/data/789019/000095017023035122/msft-20230630.htm",children:"Microsoft 2023 annual report"}),")."]}),"\n",(0,s.jsx)(n.p,{children:"Same fiscal year: one accounting estimate added US$3.7 billion; the fate of ten thousand people cost US$1.2 billion. The first sat in one explanatory paragraph of the annual report; the second made news around the world."}),"\n",(0,s.jsx)(n.h2,{id:"case-3-macronix-2016",children:"Case 3: Macronix, 2016"}),"\n",(0,s.jsxs)(n.p,{children:["In 2010, Macronix bought ProMOS's 12-inch fab in Hsinchu Science Park. Heavy depreciation plus price-cutting in the market left it with 18 consecutive quarterly losses from Q1 2012, nearly NT$24 billion in all (",(0,s.jsx)(n.a,{href:"https://finance.technews.tw/2017/03/07/mxic-capital-reduce/",children:"TechNews"}),")."]}),"\n",(0,s.jsx)(n.p,{children:"Then came 2016. I recalculated that period with my own financial-statement database:"}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{}),(0,s.jsx)(n.th,{children:"Q4 2015"}),(0,s.jsx)(n.th,{children:"Q1 2016"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Quarterly depreciation"}),(0,s.jsx)(n.td,{children:"NT$1.41 billion"}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.strong,{children:"NT$490 million"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Property, plant and equipment (net)"}),(0,s.jsx)(n.td,{children:"NT$16.6 billion"}),(0,s.jsx)(n.td,{children:"NT$16.3 billion"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Depreciation as % of revenue"}),(0,s.jsx)(n.td,{children:"25.2%"}),(0,s.jsx)(n.td,{children:"9.6%"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Revenue (QoQ)"}),(0,s.jsx)(n.td,{children:"\u2014"}),(0,s.jsx)(n.td,{children:"\u22129%"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Gross margin"}),(0,s.jsx)(n.td,{children:"8.3%"}),(0,s.jsx)(n.td,{children:"15.5%"})]})]})]}),"\n",(0,s.jsx)(n.p,{children:"Assets barely changed and revenue fell, yet depreciation dropped by two-thirds in one quarter and the gross margin doubled. Full-year depreciation was NT$5.72 billion in 2015 and about NT$2 billion in 2016."}),"\n",(0,s.jsxs)(n.p,{children:["The reason was in the news: Macronix returned to profit in Q3 2016 by adjusting the economic useful life of buildings and equipment to lower depreciation, together with cost control and growing demand (",(0,s.jsx)(n.a,{href:"https://finance.technews.tw/2017/03/07/mxic-capital-reduce/",children:"TechNews"}),"). That quarter its gross margin was 31% (",(0,s.jsx)(n.a,{href:"https://ec.ltn.com.tw/article/breakingnews/1868671/print",children:"Liberty Times"}),"), matching the 30.7% my database calculates."]}),"\n",(0,s.jsxs)(n.p,{children:["The demand recovery was real: flash prices did rise over those two years, and Macronix's gross margin reached 43% in Q4 2017 (",(0,s.jsx)(n.a,{href:"https://finance.technews.tw/2018/01/31/macronix-financial-reporting-2017/",children:"TechNews"}),"). But at the moment it turned profitable, the decisive entry was accounting: had depreciation stayed at about NT$1.4 billion a quarter, that quarter's net profit of NT$633 million (",(0,s.jsx)(n.a,{href:"https://ec.ltn.com.tw/article/breakingnews/1868671/print",children:"Liberty Times"}),") would have been a loss of about NT$300 million (a rough estimate before tax effects). After returning to profit, Macronix announced in 2017 a NT$18.65 billion capital reduction to offset losses, bringing net asset value per share back above NT$10 (",(0,s.jsx)(n.a,{href:"https://finance.technews.tw/2017/03/07/mxic-capital-reduce/",children:"TechNews"}),")."]}),"\n",(0,s.jsx)(n.h2,{id:"what-the-three-cases-share",children:"What the three cases share"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"One: all legal, all public."}),' Intel and Microsoft wrote it in their annual reports. When a Taiwan-listed company changes useful lives, it is a "change in accounting estimate" and must be announced as material information on MOPS (for example, ',(0,s.jsx)(n.a,{href:"https://news.cnyes.com/news/id/6109453",children:"Chang Heng Precision's 2025 announcement"}),"). Nobody hid anything; very few people read it."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Two: the timing always falls when the numbers most need help."})," Intel, in the year revenue fell and it was investing heavily in new fabs; Microsoft, in the same fiscal year as its layoffs; Macronix, after its eighteenth losing quarter. Accounting estimates can be adjusted at any time, but the moment they are actually adjusted is often not random."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Three: the cost does not disappear; it moves into the future."})," Extending the useful life does not reduce the total cost of a batch of machines; it only spreads it thinner and longer. Depreciation not booked today still has to be booked tomorrow; and if the machines cannot in fact last the new life, an impairment must be taken all at once. Intel wrote that risk into its own annual report."]}),"\n",(0,s.jsx)(n.p,{children:"In other words, extending depreciation lives is borrowing profit from your own future. Borrowed sensibly, it is good financial management; borrowed too heavily, the bill arrives at the worst possible time."}),"\n",(0,s.jsx)(n.h2,{id:"how-to-check-it-yourself",children:"How to check it yourself"}),"\n",(0,s.jsx)(n.p,{children:"No inside information and no paid database are needed. The quarterly reports on MOPS and some simple division are enough."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Signal"}),(0,s.jsx)(n.th,{children:"How to calculate"}),(0,s.jsx)(n.th,{children:"What looks suspicious"}),(0,s.jsx)(n.th,{children:"Could also just be"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Depreciation suddenly falls"}),(0,s.jsx)(n.td,{children:"Quarterly depreciation \xf7 net property, plant and equipment"}),(0,s.jsx)(n.td,{children:"Assets unchanged, ratio drops 20\u201330% or more in a quarter"}),(0,s.jsx)(n.td,{children:"Construction in progress not yet depreciating during an expansion; old machines fully depreciated"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Collecting cash more slowly"}),(0,s.jsx)(n.td,{children:"Average receivables \xf7 quarterly revenue \xd7 91 days"}),(0,s.jsx)(n.td,{children:"Days keep rising, above the company's own historical median"}),(0,s.jsx)(n.td,{children:"Customer mix changed; longer terms for big customers"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Goods piling up"}),(0,s.jsx)(n.td,{children:"Average inventory \xf7 quarterly cost of sales \xd7 91 days"}),(0,s.jsx)(n.td,{children:"Days keep rising while revenue grows"}),(0,s.jsx)(n.td,{children:"Stocking up ahead of price rises; higher prices inflating inventory book value"})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Selling to your own people"}),(0,s.jsx)(n.td,{children:"Related-party receivables \xf7 total receivables"}),(0,s.jsx)(n.td,{children:"Share suddenly jumps from near zero"}),(0,s.jsx)(n.td,{children:"Normal division of work within a group"})]})]})]}),"\n",(0,s.jsx)(n.p,{children:"Every signal has a normal explanation. So after spotting one, there are four more steps:"}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Quantify."})," What share of revenue is the difference? How many percentage points of gross margin does it move?"]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Confirm."}),' For Taiwanese companies, search MOPS material announcements for "change in accounting estimate" or "useful life"; for US companies, look for "Change in Accounting Estimate" in the annual report.']}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Ask about timing."})," Did the change come when the company most needed good-looking numbers?"]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Look up and down the chain."})," Put companies in the same supply chain side by side. If one company's inventory days fall while another's rise at the same time, the problem may only have changed address."]}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"a-counterexample",children:"A counterexample"}),"\n",(0,s.jsx)(n.p,{children:"The first step is the one most often skipped and the most important. In Q4 2025, Nanya Technology's quarterly depreciation fell from NT$3.55 billion to NT$2.9 billion while its assets did not shrink, and my database flagged it."}),"\n",(0,s.jsxs)(n.p,{children:["But by Q2 2026, Nanya's quarterly revenue was already NT$82.5 billion, and depreciation was only 3.5% of revenue. Even if the whole NT$650 million drop came from an accounting change, its effect on gross margin would be less than 1 percentage point. Its 79.5% gross margin was pushed up by memory prices, not made by accounting. Its Q3 gross margin rose again to 85.7%, which the company attributed to average selling prices rising more than 60% quarter on quarter (",(0,s.jsx)(n.a,{href:"https://ec.ltn.com.tw/article/breakingnews/5603609",children:"Liberty Times"}),")."]}),"\n",(0,s.jsxs)(n.p,{children:["For Macronix in 2016, the same signal moved the margin by about sixteen percentage points; for Nanya this time, by less than one. ",(0,s.jsx)(n.strong,{children:"A signal is only a starting point; the size of the effect decides whether it counts as window dressing."})]}),"\n",(0,s.jsx)(n.h2,{id:"public-is-not-the-same-as-seen",children:"Public is not the same as seen"}),"\n",(0,s.jsx)(n.p,{children:"In the three cases, nobody lied. The numbers were right, the procedures were right, the disclosures were there."}),"\n",(0,s.jsx)(n.p,{children:'The problem is where the disclosure sits. Stock charts, financial news headlines and earnings-call slides say "margin improvement", "return to profit", "record earnings per share". Why it improved is written in a paragraph on accounting estimates near the back of the annual report, or in one announcement among many in the material-information feed. Everyone reads the first; almost nobody reads the second.'}),"\n",(0,s.jsx)(n.p,{children:"Legal window dressing works not because it is well hidden, but because it does not need to be hidden at all. Most people look only at the result, not the formula."}),"\n",(0,s.jsx)(n.p,{children:"Depreciation is just the easiest kind to see. Harder to see is putting the problem on someone else's books."}),"\n",(0,s.jsx)(n.p,{children:"A company's inventory days falling may mean goods are selling well, or may only mean the goods moved into a supplier's or a downstream customer's warehouse. Looked at alone, the company's statements are clean and attractive; the problem is on someone else's books. If that someone else is not listed and has no public accounts, it is even harder to trace. Taiwan's memory industry has this shape this year: the chipmakers' inventory days plunged, while two module makers' inventory days rose to thirteen-year highs (partly because higher prices inflated the book value of inventory)."}),"\n",(0,s.jsx)(n.p,{children:"Problems like this do not go away. The chain of cause and effect always runs to the end: goods have to be sold, costs have to be fully depreciated, and the bill lands in someone's hands. Nobody knows how long it will take."}),"\n",(0,s.jsx)(n.p,{children:"So I am not a prophet. I do not know the day the bill will arrive, only that it will. This data is not useless; very few people look at it. Not looking means not seeing, and not seeing is itself the biggest risk."}),"\n",(0,s.jsx)(n.p,{children:"Depreciation lives are only one method, and the easiest to check, because there is an announcement and a formula. The ways of dressing up numbers are endless, and most do not leave such a clear trail."}),"\n",(0,s.jsxs)(n.p,{children:["The hardest to check is shifting the problem outward. The car industry has public data on this: from 2003 to 2005, US carmakers bore about 90% of the industry's warranty spending; they then shifted warranty costs onto parts suppliers step by step, and by mid-2012 the carmakers' share had fallen to 82.7%, while the suppliers' share had risen from about 10% to about 17% (",(0,s.jsx)(n.a,{href:"https://rla.org/media/article/view?id=617",children:"Warranty Week"}),"). In the summer of 2019, General Motors added new terms to its purchasing contracts: if a part is later recalled for safety reasons, the supplier bears the responsibility, even if the part was built to GM's specifications (",(0,s.jsx)(n.a,{href:"https://www.fenderbender.com/news/article/55045318/gm-hopes-to-shift-recall-burden-to-suppliers",children:"FenderBender"}),"). The consultancy Stout notes that carmakers' warranty cost-sharing programmes in practice often do not depend on who was at fault, and that the final say on how much is allocated rests with the carmaker (",(0,s.jsx)(n.a,{href:"https://www.stout.com/en/insights/article/warranty-cost-sharing-framework-resolving-disputes",children:"Stout"}),"). On paper, the big company's quality costs are low and its margins look good; the price is booked on the supplier's side \u2014 compensation, returns, rework, or simply lost orders."]}),"\n",(0,s.jsxs)(n.p,{children:["This pattern can run for a long time, because suppliers can be replaced; when one cannot hold on, the next is brought in. What it leaves behind is a string of hollowed-out suppliers. The contract terms usually only come to light when something goes wrong. In 2014, when Apple's sapphire supplier GT Advanced filed for bankruptcy, court documents revealed the contract: it could not sell sapphire to other consumer-electronics customers, and it could not change equipment, specifications or processes without Apple's consent, while Apple could change the terms at any time (",(0,s.jsx)(n.a,{href:"https://www.macrumors.com/2014/10/29/gt-advanced-bankruptcy-filing-insight/",children:"MacRumors"}),"); its plants closed and 890 people lost their jobs (",(0,s.jsx)(n.a,{href:"https://www.cultofmac.com/?p=299403",children:"Cult of Mac"}),")."]}),"\n",(0,s.jsx)(n.p,{children:"How much can outsiders see? Only the result, not the process. If the supplier is listed, its annual report usually names major customers that account for more than 10% of revenue; squeezed margins, longer receivable days and rising compensation costs all leave traces in the numbers. Put it next to its big customer and the outline may come together. If the supplier is not listed, outsiders will only find out on the day it goes under."}),"\n",(0,s.jsx)(n.p,{children:"So reading financial statements is not about finding every problem; that cannot be done. What it can do is keep you from being fooled by the numbers you can see, in the places you can see them."}),"\n",(0,s.jsx)(n.h2,{id:"data-and-method",children:"Data and method"}),"\n",(0,s.jsx)(n.p,{children:"Intel's and Microsoft's figures all come from the annual and quarterly reports the two companies filed with the US Securities and Exchange Commission. Macronix's and Nanya's figures come from my own financial-statement database: the raw data are quarterly reports on MOPS from 2013 to Q2 2026, with the original files kept, calculated quarter by quarter."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Quarterly depreciation"}),': "Depreciation expense" in the cash flow statement. Cash flow statements are year-to-date totals; single quarters are derived by subtracting adjacent quarters.']}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Gross margin"}),": gross profit (loss), net \xf7 total operating revenue."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Cross-check"}),": the database's figures for Macronix's 2015 full-year depreciation (NT$5.72 billion) and Q3 2016 gross margin (30.7%) match outside figures of NT$5.722 billion (",(0,s.jsx)(n.a,{href:"https://www.cmoney.tw/notes/note-detail.aspx?nid=174822",children:"CMoney"}),") and 31% (",(0,s.jsx)(n.a,{href:"https://ec.ltn.com.tw/article/breakingnews/1868671/print",children:"Liberty Times"}),")."]}),"\n"]}),"\n",(0,s.jsx)(n.h2,{id:"ai-disclosure",children:"AI disclosure"}),"\n",(0,s.jsx)(n.p,{children:"The database architecture and specifications were settled in discussion between me and Claude; the code was implemented to spec by Antigravity (Gemini 3.8 Flash), with every step reviewed by me. The data analysis, outside fact-checking and writing of this article were assisted by Claude Opus 5.5; the arguments, choices and conclusions are my own."}),"\n",(0,s.jsx)(n.h2,{id:"disclaimer",children:"Disclaimer"}),"\n",(0,s.jsx)(n.p,{children:"The changes in accounting estimates cited here were all disclosed publicly by the companies concerned, as required by law. This article does not accuse any company of breaking the law; it only explains how legal accounting choices affect how financial statements look. Nor is it investment advice, or a reason to buy or sell any stock."}),"\n",(0,s.jsx)(n.p,{children:"This site has no advertising budget and no paid promotion. If this article was useful to you, one share is one vote."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"AI in the Financial Statements"})}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsx)(n.li,{children:"One Industry Code, Two Opposite Moves"}),"\n",(0,s.jsx)(n.li,{children:"Change One Estimate, Earn Billions More (this article)"}),"\n",(0,s.jsx)(n.li,{children:"Where Did the Costs Go?"}),"\n",(0,s.jsx)(n.li,{children:"The Payer Starts Collecting"}),"\n",(0,s.jsx)(n.li,{children:"Margins Still at Record Highs, and the First Turning Signal Has Appeared"}),"\n"]}),"\n"]})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(h,{...e})}):h(e)}},28453(e,n,t){t.d(n,{R:()=>o,x:()=>r});var s=t(96540);const i={},a=s.createContext(i);function o(e){const n=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),s.createElement(a.Provider,{value:n},e.children)}}}]);